from decimal import Decimal
from ledgerly import audit
from ledgerly.adjustments import goodwill_credit
from ledgerly.errors import BillingError
from ledgerly.models import Invoice, LineItem

def inv(status="issued", price="50.00"):
    return Invoice("inv_1","cus_1",lines=[LineItem("Seat",1,Decimal(price))],status=status)

# basic
print(goodwill_credit(inv(), Decimal("5.00"), "late"))
# zero/negative
for a in ["0.00","-1.00"]:
    try: goodwill_credit(inv(), Decimal(a), "x")
    except BillingError as e: print("err", e.code)
# exceeds
try: goodwill_credit(inv(), Decimal("50.01"), "x")
except BillingError as e: print("err", e.code)
# not issued
try: goodwill_credit(inv("draft"), Decimal("1.00"), "x")
except BillingError as e: print("err", e.code)
# approval threshold: 1000 exactly ok, 1000.01 needs approval
big = inv(price="2000.00")
print(goodwill_credit(big, Decimal("1000.00"), "x")["amount"])
try: goodwill_credit(big, Decimal("1000.01"), "x")
except BillingError as e: print("err", e.code)
print(goodwill_credit(big, Decimal("1000.01"), "x", approved_by="mgr")["amount"])
# idempotency
audit.clear()
r1 = goodwill_credit(inv(), Decimal("5.00"), "x", idempotency_key="k1")
r2 = goodwill_credit(inv(), Decimal("5.00"), "x", idempotency_key="k1")
print(r1==r2, len(audit.events("goodwill_credit")))
# rounding banker's: 0.005 -> 0.00
print(goodwill_credit(inv(), Decimal("0.005"), "x")["amount"])
EOF"}

